import SwiftUI
import WidgetKit
struct PamEntry:TimelineEntry{let date:Date;let title:String;let subtitle:String;let value:String;let deepLink:String}
struct PamProvider:TimelineProvider{func placeholder(in context:Context)->PamEntry{PamEntry(date:.now,title:"PAM Native",subtitle:"Widget",value:"—",deepLink:"")};func getSnapshot(in context:Context,completion:@escaping(PamEntry)->Void){completion(entry())};func getTimeline(in context:Context,completion:@escaping(Timeline<PamEntry>)->Void){completion(Timeline(entries:[entry()],policy:.never))};private func entry()->PamEntry{let group="group.\((Bundle.main.bundleIdentifier ?? "").replacingOccurrences(of:".widgets",with:"" )).pam-native";let d=UserDefaults(suiteName:group);return PamEntry(date:.now,title:d?.string(forKey:"pam.widget.title") ?? "",subtitle:d?.string(forKey:"pam.widget.subtitle") ?? "",value:d?.string(forKey:"pam.widget.value") ?? "",deepLink:d?.string(forKey:"pam.widget.deepLink") ?? "")}}
struct PamWidgetView:View{let entry:PamEntry;var body:some View{VStack(alignment:.leading,spacing:4){Text(entry.title).font(.headline);Text(entry.subtitle).font(.caption).foregroundColor(.secondary);Text(entry.value).font(.title2).bold()}.padding().frame(maxWidth:.infinity,maxHeight:.infinity,alignment:.leading).background(Color(UIColor.secondarySystemBackground)).widgetURL(URL(string:entry.deepLink))}}
struct PamNativeWidget:Widget{let kind="PamNativeWidget";var body:some WidgetConfiguration{StaticConfiguration(kind:kind,provider:PamProvider()){PamWidgetView(entry:$0)}.configurationDisplayName("PAM Native").description("Live information from your app.").supportedFamilies([.systemSmall,.systemMedium])}}
@main struct PamWidgetsBundle:WidgetBundle{var body:some Widget{PamNativeWidget()}}
